const range=(k,label,min,max,step=1)=>`<label>${label}<input data-setting="${k}" type="range" min="${min}" max="${max}" step="${step}"></label>`;
export function buildUI(){return `<main><section id="home" class="home"><p class="eyebrow">LOCAL • REALTIME • WEBGL</p><h1>HAND MOTION<br/><i>VISUAL FX</i></h1><p class="lead">手の動きで、映像を彫刻する。</p><div class="cards"><article><div class="preview cube">◈</div><h2>MODE A / Gesture FX</h2><p>ジェスチャーでARオブジェクト、変身、粒子を制御。</p><button id="startA">START GESTURE FX</button></article><article><div class="preview geo">◇</div><h2>MODE B / Hand Geometry</h2><p>両手の指先から映像フレームと立体を生成。</p><button id="startB">START GEOMETRY FX</button></article></div><p id="error" class="error"></p></section><section id="studio" hidden><header><button id="back">← HOME</button><strong>HAND MOTION / <span id="status">STANDBY</span></strong><div><button id="flip">CAMERA</button><button id="fullscreen">FULL</button><button id="shot">SHOT</button><button id="record">REC</button></div></header><div class="layout"><aside class="modes"><p>MODE SELECT</p>${[['cube','Hand Cube AR'],['invisible','Invisible / Glass / Chrome'],['dissolve','Particle Dissolve'],['frame','Hand Frame'],['twist','Hand Twist'],['volume','Hand Volume'],['anime','Anime Frame']].map(([v,n])=>`<button data-mode="${v}">${n}</button>`).join('')}</aside><section id="stage"><video id="camera" playsinline muted></video><canvas id="output"></canvas><canvas id="overlay"></canvas><div class="hint">OPEN: normal / FIST: transform<br/>2 hands: frame</div></section><aside class="controls"><p>PARAMETERS</p><div data-mode-panel="cube">${range('size','CUBE SIZE',.4,2,.1)}${range('speed','ROTATION',.1,3,.1)}</div><div data-mode-panel="invisible" hidden><label>STYLE<select data-setting="transform"><option value="glass">GLASS</option><option value="chrome">CHROME</option><option value="invisible">INVISIBLE</option></select></label><button id="capture">CAPTURE BACKGROUND</button>${range('strength','STRENGTH',0,1,.05)}</div><div data-mode-panel="dissolve" hidden>${range('particles','PARTICLES',100,2000,50)}${range('speed','SPEED',.1,3,.1)}${range('size','SIZE',1,8,1)}</div><div data-mode-panel="frame" hidden><label>FILTER<select data-setting="frameEffect"><option value="pop">POP ART</option><option value="pixel">8-BIT</option><option value="invert">COLOR INVERT</option></select></label></div><div data-mode-panel="twist" hidden><p>Perspective / elastic geometry is controlled by the two-hand frame.</p></div><div data-mode-panel="volume" hidden>${range('size','VOLUME SCALE',.4,2,.1)}</div><div data-mode-panel="anime" hidden><p>Cel color treatment and frame mask.</p></div><hr/><label class="check"><input data-setting="debug" type="checkbox"> LANDMARK DEBUG</label><label class="check"><input data-setting="mirror" type="checkbox"> MIRROR VIDEO</label><button id="reset">RESET SETTINGS</button><button id="export">EXPORT JSON</button><button id="import">IMPORT JSON</button><input id="importFile" type="file" accept="application/json" hidden/></aside></div><footer id="metrics">0 FPS · 0/2 HANDS · —</footer></section></main>`}
